// Seed — payer scorecards (amendment 41). One archived snapshot, hand-frozen:
// the National Social Security Fund's card for August 2026, version 1,
// generated by the CMO on 2 September. A scorecard is what the engine read
// on the day it was made, so these figures are written out rather than
// computed — the archive renders a row from its own `figures` and never
// asks the engine — and they are kept plausible against the seeded
// registers (a handful of NSSF denials in August, one appeal decided, one
// recovery paid, nothing separated out). The first scorecard generated live
// is SC-2026-0002.

const usd = (n) => `$${Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const pct = (n) => (n == null ? '—' : `${(n * 100).toFixed(1)}%`);
const dd = (n) => (n == null ? '—' : `${n} d`);
const text = (format, v) => (v == null ? '—' : format === 'pct' ? pct(v) : format === 'usd' ? usd(v) : format === 'days' ? dd(v) : String(v));
const deltaText = (format, d) => (d == null ? '—' : format === 'pct' ? `${d > 0 ? '+' : ''}${(d * 100).toFixed(1)} pts` : format === 'usd' ? `${d > 0 ? '+' : ''}${usd(d)}` : `${d > 0 ? '+' : ''}${d} d`);
const GOOD_UP = new Set(['recoveryRate', 'overturnRate', 'firstPassPrevention']);

/** One headline line: this period, the one before, and every payer over the same month. */
const line = (key, label, short, format, dateBoundary, value, count, prior, priorCount, allPayers, pending = null) => ({
  key, label, short, format, dateBoundary, value, text: text(format, value), count,
  prior: { value: prior, text: text(format, prior), count: priorCount },
  delta: value != null && prior != null ? Math.round((value - prior) * 10000) / 10000 : null,
  deltaText: deltaText(format, value != null && prior != null ? Math.round((value - prior) * 10000) / 10000 : null),
  improved: value == null || prior == null ? null : GOOD_UP.has(key) ? value > prior : value < prior,
  allPayers: { value: allPayers, text: text(format, allPayers) },
  pending,
});

